(5738554, 833986, 42256, '<td valign="top">I like the simplicity of the shot, almost looks like a Canadian flag with wrong background! IMO red border is distracting and reason why i took 1 point off.. 8</td>', 'I like the simplicity of the shot, almost looks like a Canadian flag with wrong background! IMO red border is distracting and reason why i took 1 point off.. 8', '2009-11-23 17:04:07.000000', NULL, 1),
(5738558, 834186, 42256, '<td valign="top">This is really sharp, I would have missed it if I had not seen it the second time! Also fits the challenge really well! Would have loved to see a little more play with curves in photoshop but I am just being picky!  bumping up to 8</td>', 'This is really sharp, I would have missed it if I had not seen it the second time! Also fits the challenge really well! Would have loved to see a little more play with curves in photoshop but I am just being picky!  bumping up to 8', '2009-11-23 17:05:18.000000', NULL, 1),
(5738559, 833850, 42256, '<td valign="top">This is beautifully lit, love the duotone and emotions shown in the shot.  I just don''t like the background, I have a feeling its a bed-sheet to give a faux wallpaper look, but the wrinkels are giving it away. Still one of the better shots in the challenge! 8</td>', 'This is beautifully lit, love the duotone and emotions shown in the shot.  I just don''t like the background, I have a feeling its a bed-sheet to give a faux wallpaper look, but the wrinkels are giving it away. Still one of the better shots in the challenge! 8', '2009-11-23 17:07:06.000000', NULL, 1),
(5738565, 833536, 42256, '<td valign="top">This shot fits the challenge really well! Double decker bus with Trafalgar Square, umbrella and the rain all are just really getting the point across.  Now the negatives  - I wish you had somehow avoided the tree, moved further down the walkway.  Shot seems a little overexposed and over saturated (leaves on top) 7</td>', 'This shot fits the challenge really well! Double decker bus with Trafalgar Square, umbrella and the rain all are just really getting the point across.  Now the negatives  - I wish you had somehow avoided the tree, moved further down the walkway.  Shot seems a little overexposed and over saturated (leaves on top) 7', '2009-11-23 17:13:35.000000', NULL, 1),
(5738567, 834207, 42256, '<td valign="top">Beautiful Landscape! Fits the challenge well.. negatives - DOF is not deep enough.  I almost want to see more of the landscape, the crop is just not working, clouds on the top are not adding anything more, cropping them closer might have worked better. 7</td>', 'Beautiful Landscape! Fits the challenge well.. negatives - DOF is not deep enough.  I almost want to see more of the landscape, the crop is just not working, clouds on the top are not adding anything more, cropping them closer might have worked better. 7', '2009-11-23 17:15:44.000000', NULL, 1),
(5738569, 833935, 42256, '<td valign="top">Great shot, nicely symmetrical.  I am glad you made this a B&amp;W, really works well.. although that said, B&amp;W is not offering enough drama to take it to the next level, it needs more contrast to make the Eiffel tower really pop out! 8</td>', 'Great shot, nicely symmetrical.  I am glad you made this a B&W, really works well.. although that said, B&W is not offering enough drama to take it to the next level, it needs more contrast to make the Eiffel tower really pop out! 8', '2009-11-23 17:18:17.000000', NULL, 1),
(5738573, 833898, 42256, '<td valign="top">It''s such a beautiful iconic shot, I really wish you had somehow managed to avoid the boat.. you had the perfect frame nice use of B&amp;W and a wonderful shot.  Only negative in this shot for me is the boat! 7</td>', 'It''s such a beautiful iconic shot, I really wish you had somehow managed to avoid the boat.. you had the perfect frame nice use of B&W and a wonderful shot.  Only negative in this shot for me is the boat! 7', '2009-11-23 17:21:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5738645, 833684, 106233, '<td valign="top">Very balanced composition, and the red colors are an interesting touch to it!</td>', 'Very balanced composition, and the red colors are an interesting touch to it!', '2009-11-23 17:51:00.000000', NULL, 1),
(5738655, 833330, 106233, '<td valign="top">I think you had a very difficult trade off between the right exposure of the car/ground vs the right exposure of the sun... but I think you made a good choice. Maybe a little darker, but I´m not sure about it... I would also prefer a less centered horizon...<br/>The colors and DOF are great, indeed.<br/>Congrats! <br/>PS.: I just dont know what country you are showing here... ;)</td>', 'I think you had a very difficult trade off between the right exposure of the car/ground vs the right exposure of the sun... but I think you made a good choice. Maybe a little darker, but I´m not sure about it... I would also prefer a less centered horizon...The colors and DOF are great, indeed.Congrats! PS.: I just dont know what country you are showing here... ;)', '2009-11-23 18:04:50.000000', NULL, 1),
(5738658, 833654, 106233, '<td valign="top">Very strong picture.<br/>Great light (but I would like to see his legs - even if on the shadow)</td>', 'Very strong picture.Great light (but I would like to see his legs - even if on the shadow)', '2009-11-23 18:07:16.000000', NULL, 1),
(5738660, 833829, 106233, '<td valign="top">Nice picture, but I would prefer more contrast, and a more wide framing.</td>', 'Nice picture, but I would prefer more contrast, and a more wide framing.', '2009-11-23 18:10:01.000000', NULL, 1),
(5738662, 833990, 106233, '<td valign="top">Beautiful composition! Great light and framing! I would prefer if the sky wasnt washed, but you did a great job! Congrats!</td>', 'Beautiful composition! Great light and framing! I would prefer if the sky wasnt washed, but you did a great job! Congrats!', '2009-11-23 18:12:01.000000', NULL, 1),
(5738666, 833986, 106233, '<td valign="top">Great idea! Beautiful image!</td>', 'Great idea! Beautiful image!', '2009-11-23 18:15:00.000000', NULL, 1),
(5738667, 834175, 106233, '<td valign="top">Good idea, but for me the composition is too busy.</td>', 'Good idea, but for me the composition is too busy.', '2009-11-23 18:16:12.000000', NULL, 1),
(5738670, 834258, 106233, '<td valign="top">Great idea and composition!<br/>The colors are great, but I think I would prefer if the fill light was a little darker. Anyway... nice job!</td>', 'Great idea and composition!The colors are great, but I think I would prefer if the fill light was a little darker. Anyway... nice job!', '2009-11-23 18:20:20.000000', NULL, 1),
(5738673, 834005, 106233, '<td valign="top">Nice picture.<br/>I like the composition, but I think you could depict the same spirit with less objects in the frame (It is a little busy, IMO).<br/>The sepia was a great option!</td>', 'Nice picture.I like the composition, but I think you could depict the same spirit with less objects in the frame (It is a little busy, IMO).The sepia was a great option!', '2009-11-23 18:24:16.000000', NULL, 1),
(5738676, 834053, 106233, '<td valign="top">Nice colors! I would prefer a less busy foreground.</td>', 'Nice colors! I would prefer a less busy foreground.', '2009-11-23 18:26:04.000000', NULL, 1),
(5738680, 834240, 106233, '<td valign="top">Simple, beautiful and with a clear message. Good light and DOF.<br/>Very nice job. I would prefer if the legs were on the diagonal to the left, to give more use to the upper left of the frame. But you did a great job. Congrats!</td>', 'Simple, beautiful and with a clear message. Good light and DOF.Very nice job. I would prefer if the legs were on the diagonal to the left, to give more use to the upper left of the frame. But you did a great job. Congrats!', '2009-11-23 18:29:55.000000', NULL, 1),
(5738684, 834194, 106233, '<td valign="top">Beautiful place! Great light!</td>', 'Beautiful place! Great light!', '2009-11-23 18:37:37.000000', NULL, 1),
(5738686, 834285, 106233, '<td valign="top">Good work on the light and composition.</td>', 'Good work on the light and composition.', '2009-11-23 18:39:54.000000', NULL, 1),
(5738687, 834016, 106233, '<td valign="top">Good texture! I would prefer if the upper left was a little darker.</td>', 'Good texture! I would prefer if the upper left was a little darker.', '2009-11-23 18:41:09.000000', NULL, 1),
(5738693, 833895, 106233, '<td valign="top">Great colors, light and composition!</td>', 'Great colors, light and composition!', '2009-11-23 18:53:59.000000', NULL, 1),
(5738696, 834286, 106233, '<td valign="top">I would prefer a colored version of it, because I am really not sure if the foreground is sand or water... Choosing B&amp;W, maybe it would be better with more contrast, to boost the clouds in the sky..</td>', 'I would prefer a colored version of it, because I am really not sure if the foreground is sand or water... Choosing B&W, maybe it would be better with more contrast, to boost the clouds in the sky..', '2009-11-23 18:57:49.000000', NULL, 1),
(5738699, 833935, 106233, '<td valign="top">Very good simmetry, and good choice on B&amp;W. Maybe more contrast would be nice.</td>', 'Very good simmetry, and good choice on B&W. Maybe more contrast would be nice.', '2009-11-23 19:00:02.000000', NULL, 1),
(5738702, 834186, 106233, '<td valign="top">Love the colors, sharpness and light! Great choice to depict London! Maybe a straight framing would be better to show the british formality, but the tilted option is nice too!</td>', 'Love the colors, sharpness and light! Great choice to depict London! Maybe a straight framing would be better to show the british formality, but the tilted option is nice too!', '2009-11-23 19:06:11.000000', NULL, 1),
(5738713, 833574, 106233, '<td valign="top">Good colors and sharpness. Nice composition too!!  Great job.</td>', 'Good colors and sharpness. Nice composition too!!  Great job.', '2009-11-23 19:12:35.000000', NULL, 1),
(5738715, 834247, 106233, '<td valign="top">Nice subject. Good composition and exposure. It just seems a little overprocessed for me...</td>', 'Nice subject. Good composition and exposure. It just seems a little overprocessed for me...', '2009-11-23 19:18:04.000000', NULL, 1),
(5738720, 834049, 106233, '<td valign="top">Great idea and composition, but I think that you could have improved the exposure, metering the sky and using some fill flash to give more colors to the picture.</td>', 'Great idea and composition, but I think that you could have improved the exposure, metering the sky and using some fill flash to give more colors to the picture.', '2009-11-23 19:20:34.000000', NULL, 1),
(5738723, 834204, 106233, '<td valign="top">Dont know what it is, and also what country is showed here... but this seems tasteful!<br/>Nice work with the light!</td>', 'Dont know what it is, and also what country is showed here... but this seems tasteful!Nice work with the light!', '2009-11-23 19:23:39.000000', NULL, 1),
(5738771, 834285, 38478, '<td valign="top">Nice shot..and nice pun :)</td>', 'Nice shot..and nice pun :)', '2009-11-23 20:37:12.000000', NULL, 1),
(5738772, 834286, 38478, '<td valign="top">I like the b&amp;w processing in the clouds, but I find the lines in the water in front to be too distracting.</td>', 'I like the b&w processing in the clouds, but I find the lines in the water in front to be too distracting.', '2009-11-23 20:39:56.000000', NULL, 1),
(5738775, 834271, 38478, '<td valign="top">I really like the energy!</td>', 'I really like the energy!', '2009-11-23 20:40:32.000000', NULL, 1),
(5738781, 834175, 38478, '<td valign="top">Nice focus on the grapes, and good colors, and while I know the OOF on the bottle is intentional, I don''t think it works here.</td>', 'Nice focus on the grapes, and good colors, and while I know the OOF on the bottle is intentional, I don''t think it works here.', '2009-11-23 20:44:28.000000', NULL, 1),
(5738794, 833817, 38478, '<td valign="top">Good depth, with the lines leading us all the way to the back and then back to the front. Excellent processing too, nice and sharp without too much.</td>', 'Good depth, with the lines leading us all the way to the back and then back to the front. Excellent processing too, nice and sharp without too much.', '2009-11-23 20:52:24.000000', NULL, 1),
(5738796, 834049, 38478, '<td valign="top">Rather dark and flat</td>', 'Rather dark and flat', '2009-11-23 20:53:51.000000', NULL, 1),
(5738802, 834005, 112004, '<td valign="top">Nicely composed.</td>', 'Nicely composed.', '2009-11-23 21:01:13.000000', NULL, 1),
(5738805, 834285, 112004, '<td valign="top">Great lighting, very crisp shot.</td>', 'Great lighting, very crisp shot.', '2009-11-23 21:02:01.000000', NULL, 1),
(5738807, 834005, 38478, '<td valign="top">It could use a bit more contrast.</td>', 'It could use a bit more contrast.', '2009-11-23 21:02:21.000000', NULL, 1),
