(5739150, 834268, 38930, '<td valign="top">There''s a ribbon picture!</td>', 'There''s a ribbon picture!', '2009-11-24 01:57:36.000000', NULL, 1),
(5739151, 833817, 38930, '<td valign="top">Nice way of looking at the challenge, and great picture!</td>', 'Nice way of looking at the challenge, and great picture!', '2009-11-24 01:57:51.000000', NULL, 1),
