(5739160, 834072, 38930, '<td valign="top">Great shot!</td>', 'Great shot!', '2009-11-24 02:00:20.000000', NULL, 1),
(5739161, 834150, 38930, '<td valign="top">Awesome picture!  You were in the right place at the right time.  Nice work :)</td>', 'Awesome picture!  You were in the right place at the right time.  Nice work :)', '2009-11-24 02:00:43.000000', NULL, 1),
