(5739165, 834139, 38930, '<td valign="top">Very cool!  Nice shot... the colors are really neat</td>', 'Very cool!  Nice shot... the colors are really neat', '2009-11-24 02:01:35.000000', NULL, 1),
(5739166, 834005, 38930, '<td valign="top">Perfect concept, and great job with this picture!</td>', 'Perfect concept, and great job with this picture!', '2009-11-24 02:02:05.000000', NULL, 1),
(5739167, 834207, 38930, '<td valign="top">This is so great!  Awesome colors</td>', 'This is so great!  Awesome colors', '2009-11-24 02:02:17.000000', NULL, 1),
