(5739169, 834265, 38930, '<td valign="top">Great idea!</td>', 'Great idea!', '2009-11-24 02:03:01.000000', NULL, 1),
(5739170, 834049, 38930, '<td valign="top">Nice concept</td>', 'Nice concept', '2009-11-24 02:03:14.000000', NULL, 1),
(5739171, 834188, 38930, '<td valign="top">Wow, this is great!  It stands out from all the other pictures in this challenge (in a good way!) and I really like it :)</td>', 'Wow, this is great!  It stands out from all the other pictures in this challenge (in a good way!) and I really like it :)', '2009-11-24 02:03:44.000000', NULL, 1),
